apply.css:
#root { --sl-background:#dfeee6; --sl-ink:#153e35; --sl-muted:#507566; --sl-accent:#22795e; --sl-surface:#f3faf5; --sl-border:#adc9b9; --sl-radius:28px; background:#dfeee6 !important; color:#153e35 !important; font-family:Arial, sans-serif !important; }
#root * { font-family:inherit !important; }
#root :is(h1,h2,h3,[data-sl-heading]) { font-family:Arial, sans-serif !important; color:#153e35 !important; }
#root [data-sl-muted] { color:#507566 !important; }
#root [data-sl-accent] { color:#22795e !important; }
#root [data-sl-surface] { background:#f3faf5 !important; color:#153e35 !important; border-color:#adc9b9 !important; border-radius:28px !important; }
#root [data-sl-fill] { background:#22795e !important; }
